import { copy } from '../lib/copy';
import markUrl from './brand-mark.svg';
import { wordmarkCareer, wordmarkFut, wordmarkSize } from './brand-paths';

// Fut Career lockup: the football mark on the lime square and, on the dark
// panel, the wordmark with white FUT and lime CAREER. Files are generated by
// mobile/scripts/brand-svg.py.
// stacked: the large centred lockup of the sign-in screen (mark above the
// wordmark, no pilot line).
export function Brand({ stacked = false }: { stacked?: boolean }) {
  if (stacked) {
    return (
      <div className="brand brand-stacked" role="img" aria-label={copy.brand}>
        <img className="brand-mark" src={markUrl} alt="" />
        <svg
          className="brand-word"
          viewBox={'0 0 ' + wordmarkSize.width + ' ' + wordmarkSize.height}
          aria-hidden="true"
        >
          <path d={wordmarkFut} className="brand-word-fut" />
          <path d={wordmarkCareer} className="brand-word-career" />
        </svg>
      </div>
    );
  }
  return (
    <div className="brand" role="img" aria-label={copy.brand}>
      <img className="brand-mark" src={markUrl} alt="" />
      <div>
        <svg
          className="brand-word"
          viewBox={'0 0 ' + wordmarkSize.width + ' ' + wordmarkSize.height}
          aria-hidden="true"
        >
          <path d={wordmarkFut} className="brand-word-fut" />
          <path d={wordmarkCareer} className="brand-word-career" />
        </svg>
        <span>{copy.pilot}</span>
      </div>
    </div>
  );
}
